// ?bfmeLess@@YA_NPBVBfmeItemEG@@0@Z
bool __cdecl bfmeLess(const BfmeItemEG *first, const BfmeItemEG *second)
{
	if (first->m_bfmeMajor < second->m_bfmeMajor)
		return true;

	if (first->m_bfmeMajor > second->m_bfmeMajor)
		return false;

	return first->m_bfmeMinor < second->m_bfmeMinor;
}

